local_vars = {}
exec(student_code, {}, local_vars)

# Check Task 1: Should be a set
subs = local_vars.get('subscriber_emails')
if subs is None:
    raise AssertionError("Task 1: 'subscriber_emails' variable not found. Did you assign it?")
if not isinstance(subs, set):
    raise AssertionError('Task 1: Subscriber emails should be a SET to prevent duplicate entries. Use curly braces: {item1, item2}')
if subs != {'dev@example.com', 'user@test.org'}:
    raise AssertionError("Task 1: Set should contain exactly 'dev@example.com' and 'user@test.org'")

# Check Task 2: Should be a list
stocks = local_vars.get('stock_history')
if stocks is None:
    raise AssertionError("Task 2: 'stock_history' variable not found. Did you assign it?")
if not isinstance(stocks, list):
    raise AssertionError('Task 2: Stock history should be a LIST for an ordered, growing sequence. Use square brackets: [item1, item2, item3]')
if stocks != [142.50, 143.75, 141.20]:
    raise AssertionError("Task 2: List should contain exactly [142.50, 143.75, 141.20] in that order")

# Check Task 3: Should be a dictionary
catalog = local_vars.get('price_catalog')
if catalog is None:
    raise AssertionError("Task 3: 'price_catalog' variable not found. Did you assign it?")
if not isinstance(catalog, dict):
    raise AssertionError('Task 3: Price catalog should be a DICTIONARY for key-value mapping. Use curly braces with colons: {key: value}')
if catalog != {'A101': 19.99, 'B202': 25.50}:
    raise AssertionError("Task 3: Dictionary should map 'A101' to 19.99 and 'B202' to 25.50")

# Check Task 4: Should be a tuple
response = local_vars.get('success_response')
if response is None:
    raise AssertionError("Task 4: 'success_response' variable not found. Did you assign it?")
if not isinstance(response, tuple):
    raise AssertionError('Task 4: Response code should be a TUPLE because it is a fixed constant. Use parentheses: (item1, item2)')
if response != (200, 'OK'):
    raise AssertionError("Task 4: Tuple should contain exactly (200, 'OK')")

print('TEST_PASSED')
